companionBundle.script:
const root = document.getElementById('app');

root.innerHTML = `
  <main class="card">
    <div class="eyebrow">DIESER PC</div>
    <div class="count" id="count">–</div>
    <h1>Projekte</h1>
    <p id="status">Der aktuelle Stand wird geladen …</p>
    <div class="actions">
      <button id="refresh">Neu laden</button>
      <button class="quiet" id="copy" disabled>Wert kopieren</button>
    </div>
  </main>
`;

let latestCount = null;

async function refresh() {
  const status = document.getElementById('status');
  status.textContent = 'Der aktuelle Stand wird geladen …';
  try {
    const result = await teydra.invoke('count-projects');
    latestCount = result.projectCount;
    document.getElementById('count').textContent = String(latestCount);
    document.getElementById('copy').disabled = false;
    status.textContent = `Zuletzt geprüft: ${new Date(result.measuredAt).toLocaleTimeString()}`;
    await teydra.state.save({ latestCount, measuredAt: result.measuredAt });
  } catch (error) {
    status.textContent = error instanceof Error ? error.message : 'Der PC hat nicht geantwortet.';
  }
}

document.getElementById('refresh').addEventListener('click', refresh);
document.getElementById('copy').addEventListener('click', async () => {
  if (latestCount === null) return;
  await teydra.clipboard.write(`${latestCount} Projekte`);
});

teydra.ready(async (context) => {
  const saved = await teydra.state.load();
  if (saved && Number.isInteger(saved.latestCount)) {
    latestCount = saved.latestCount;
    document.getElementById('count').textContent = String(latestCount);
    document.getElementById('copy').disabled = false;
    document.getElementById('status').textContent = 'Gespeicherter Stand – wird aktualisiert …';
  }
  await refresh();
});

companionBundle.style:
:root {
  color-scheme: dark;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #0b0b0d;
  color: #f7f7f8;
}

* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 24px; }
.card { width: min(100%, 420px); padding: 28px; border: 1px solid #2f2b3b; border-radius: 28px; background: #17151d; }
.eyebrow { color: #a78bfa; font-size: 12px; font-weight: 800; letter-spacing: 0.14em; }
.count { margin-top: 22px; font-size: 76px; font-weight: 750; line-height: 0.9; }
h1 { margin: 8px 0 0; font-size: 28px; }
p { min-height: 42px; margin: 18px 0 24px; color: #aaa5b5; line-height: 1.45; }
.actions { display: grid; gap: 10px; }
button { appearance: none; border: 0; border-radius: 16px; padding: 15px 18px; background: #a78bfa; color: #17121f; font: inherit; font-weight: 750; }
button.quiet { background: #282431; color: #ece9f4; }
button:disabled { opacity: 0.45; }
